        },
        screens() {
            let screens = this.$store.getters["builder/screens"];
            if (!screens) {
                return [];
            }
            return Object.entries(screens).sort(([, b1], [, b2]) => b1.width - b2.width);
        },
        screen() {
            return this.$store.getters["builder/screen"];
        },
        screenMinW() {
            let rs = [];
            for (let i in this.screens) {
                let screen = this.$helpers.copy(this.screens[i]);
                screen[1].width = i === "0" ? 0 : parseInt(this.screens[i - 1][1].width) + 1;
                rs.push(screen);
            }
            return rs;
        },
        breakpoints() {
            let bp = {},
                settings = this.data.settings;
            let ops = { perPage: 'itemsPerView', gap: 'itemsSpace' };

            this.screenMinW.forEach(([, v]) => {
                bp[v.width] = {};
                Object.keys(ops).forEach((op) => {
                    let key = v.name === "desktop" ? ops[op] : ops[op] + "__" + v.name;
                    bp[v.width][op] = settings[key];
                });
            });

            return bp;
        },
        thumbsBreakpoints() {
            let bp = {},
                settings = this.data.settings;

            let ops = ["perPage", "gap", "thumbnail_position"];
            this.screenMinW.forEach(([, v]) => {
                bp[v.width] = {};
                ops.forEach((op) => {
                    let key = v.name === "desktop" ? op : op + "__" + v.name,
                        position_key = v.name === "desktop" ? 'thumbnail_position' : 'thumbnail_position' + "__" + v.name;

                    if (op === 'perPage') {
                        let originalKey = v.name === "desktop" ? 'slidesPerView' : 'slidesPerView' + "__" + v.name;
                        if (['row', 'row-reverse'].includes(settings[position_key])) {
                            bp[v.width][op] = 1;
                        } else {
                            bp[v.width][op] = settings[originalKey];
                        }
                    } else if (op === 'gap') {
                        let originalKey = v.name === "desktop" ? 'spaceBetween' : 'spaceBetween' + "__" + v.name;
                        bp[v.width][op] = settings[originalKey];
                    } else {
                        bp[v.width][op] = settings[key];
                    }
                });
            });
            return bp;
