                    const doc = window.document || document;
                    if (!doc) return false;
                    const rtlLanguages = ['ar', 'arc', 'dv', 'fa', 'ha', 'he', 'khw', 'ks', 'ku', 'ps', 'ur'];
                    const htmlDir = doc.documentElement?.dir ||
                                    doc.documentElement?.getAttribute('dir') ||
                                    doc.querySelector('html')?.getAttribute('dir');
                    if (htmlDir === 'rtl') return true;
                    const bodyDir = doc.body?.dir || doc.body?.getAttribute('dir');
                    if (bodyDir === 'rtl') return true;
                    if (doc.documentElement) {
                        const computedDir = window.getComputedStyle(doc.documentElement).direction;
                        if (computedDir === 'rtl') return true;
                    }
                    if (doc.body) {
                        const computedBodyDir = window.getComputedStyle(doc.body).direction;
                        if (computedBodyDir === 'rtl') return true;
                    }
                    const lang = doc.documentElement?.lang ||
                                 doc.documentElement?.getAttribute('lang') ||
                                 doc.querySelector('html')?.getAttribute('lang');
                    if (lang && rtlLanguages.includes(lang.toLowerCase())) {
                        return true;
                    }
                    return false;
                }

                // eslint-disable-next-line @typescript-eslint/no-this-alias
                const _this = this,sectionId = this.id;
                const $el = this.$el,isLive = this.isLive;

