                                const $selector = _this.$el.querySelector(
                                    ".ecom-product-single__media--thumbs"
                                );
                                let isRTL = $selector.dataset?.direction === 'rtl';
                                if (isLive && checkIsRTLHelper) {
                                    isRTL = checkIsRTLHelper();
