                                let data = JSON.parse($selector.dataset.breakpoints);
                                Object.keys(data).forEach(s=>{
                                    let key  = 'thumbnail_position';
                                    data[s].direction = ['row','row-reverse'].includes(data[s][key]) ? 'ttb': isRTL ? 'rtl' : 'ltr';
                                })
                                if(isLive ? $selector.hasChildNodes() : $selector.querySelector('.ec_splide__list')) {
                                    const isMobile = window.matchMedia('(max-width: 767px)').matches;
                                    const isTablet = window.matchMedia('(min-width: 768px) and (max-width: 1024px)').matches;
                                    const isDesktop = window.matchMedia('(min-width: 1025px)').matches;
                                    const heightAdjust = (['row','row-reverse'].includes(thumbnail_position) && isDesktop) ||
                                        (['row','row-reverse'].includes(thumbnail_position__tablet) && isTablet) ||
                                        (['row','row-reverse'].includes(thumbnail_position__mobile) && isMobile);
                                    const navOption = {
