                                    {% assign videoUrl = '' %}
                                    {% for source in media.sources %}
                                        {% if source.format == "mp4" %}
                                            {% assign videoUrl = source.url %}
                                            {% break %}
                                        {% endif %}
                                    {% endfor %}
                                    <div data-stopdrag="true" class="${classNameContainer} ${this.data.settings?.grid_items ? ` ecom-col-lg-` + this.data.settings?.grid_items : ''}${this.data.settings?.grid_items__tablet ? ` ecom-col-md-` + this.data.settings?.grid_items__tablet : ''}${this.data.settings?.grid_items__mobile ? ` ecom-col-` + this.data.settings?.grid_items__mobile : ''} ecom-product-single__media--video ecom-product-single__media--full ecom-swiper-no-swiping" data-position="{{media.position}}" style="--img_padding: ${this.heightValue('desktop') ? this.heightValue('desktop') : '{{ media_ration | divided_by:  img_padding }}%'};--img_padding__tablet: ${this.heightValue('tablet') ? this.heightValue('tablet') : '{{ media_ration | divided_by:  img_padding__tablet }}%'};--img_padding__mobile: ${this.heightValue('mobile') ? this.heightValue('mobile') : '{{ media_ration | divided_by: img_padding__mobile }}%'}" ${this.image_action === "lightbox" ? `ecom-modal-source="{{videoUrl}}"  ecom-modal='video'`: ""}>
                                        {{ media | video_tag: image_size:'master', class: 'ecom-media-video', controls: ${this.data.settings?.video_control}, autoplay: ${this.data.settings?.video_auto_play}, muted: ${this.data.settings?.video_mute},loop: ${this.data.settings?.video_loop} }}
                                        <button  class="ecom-product-single__media--play-control"
                                        type="button"
                                        >
                                            <span class="ecom-product-single__media--play-control-wrapper">
                                                <span class="visually-hidden">Play video</span>
                                                ${this.data.settings?.video_icon ? this.data.settings.video_icon.value : ''}
                                            </span>
                                        </button>
                                    </div>
                                {% when 'model' %}
                                    <div class="${classNameContainer} ${this.data.settings?.grid_items ? ` ecom-col-lg-` + this.data.settings?.grid_items : ''}${this.data.settings?.grid_items__tablet ? ` ecom-col-md-` + this.data.settings?.grid_items__tablet : ''}${this.data.settings?.grid_items__mobile ? ` ecom-col-` + this.data.settings?.grid_items__mobile : ''} ecom-swiper-no-swiping  ecom-product-single__media--model ecom-product-single__media--full" data-stopdrag="true" data-position="{{media.position}}">
                                        <div class="ecom-product-single__media--model-wrapper">
                                            {{ media | model_viewer_tag: image_size:'master', reveal: 'interaction', toggleable: true, data-model-id: media.id }}
                                        </div>
                                    </div>
                                {% else %}
                                    <div data-media-type="{{media.media_type}}" class="${classNameContainer} ${this.data.settings?.grid_items ? ` ecom-col-lg-` + this.data.settings?.grid_items : ''}${this.data.settings?.grid_items__tablet ? ` ecom-col-md-` + this.data.settings?.grid_items__tablet : ''}${this.data.settings?.grid_items__mobile ? ` ecom-col-` + this.data.settings?.grid_items__mobile : ''} ecom-swiper-no-swiping ecom-product-single__media--full" data-position="{{media.position}}">
                                        <div class="ecom-product-single__media" style="--img_padding: {{ media_ration | divided_by:  img_padding }}%;--img_padding__tablet: {{ media_ration | divided_by: img_padding__tablet }}%;--img_padding__mobile: {{ media_ration | divided_by: img_padding__mobile }}%;">
                                            {{ media | media_tag: image_size:'master', class: 'ecom-product-single__media--item' }}
                                        </div>
                                    </div>
                                {% endcase %}
                            {%- endfor -%}
                        </div>
                    `,
                    preview: `
                            <div class="ecom-swiper-wrapper ecom-product-single__media-images">
                                <div class="${classNameContainer}">
                                    <img src="https://cdn2.shopify.com/s/files/1/0121/5945/1236/files/backpack.svg?7273" />
                                </div>
                                <div class="${classNameContainer}">
                                    <img loading="lazy" src="https://cdn2.shopify.com/s/files/1/0121/5945/1236/files/shoe.svg?7273" />
                                </div>
                                <div class="${classNameContainer}">
                                    <img loading="lazy" src="https://cdn2.shopify.com/s/files/1/0121/5945/1236/files/shoe.svg?7273" />
                                </div>
                            </div>
                    `
                },
                product_media: {
                    code: `
                    {% comment %}
                        Reactivity
                        *this.data.settings.image_action
                        *this.data.settings.enable_zoom
                        *this.data.settings.grid_advance_number_images
                    {% endcomment %}

                    ${label}

                    {% assign img_padding = ${this.data.settings?.itemsPerView ? this.data.settings?.itemsPerView : 1} | times: 1 %}
                    {% assign img_padding__tablet = ${this.data.settings?.itemsPerView__tablet ? this.data.settings?.itemsPerView__tablet : 1} | times: 1 %}
                    {% assign img_padding__mobile = ${this.data.settings?.itemsPerView__mobile ? this.data.settings?.itemsPerView__mobile : 1} | times: 1 %}

                    <div class="ec_splide__list ecom-swiper-wrapper ecom-product-single__media--images ecom-swiper-wrapper ecom-product-single__media--images-layout__${this.layout}{% if product.images.size == 1 %} ecom-product-single__only{% endif %}">
                        {% assign use_limit = ${this.data.settings.use_limit_images}  %}
                        {% assign limit_images = ${this.data.settings.grid_advance_number_images}  %}
                        {% assign variant_images = product.images | where: 'attached_to_variant?', true | map: 'src' %}
                        {% for media in product.media %}
                            {% assign media_ration = 1 | divided_by: media.aspect_ratio | times: 100 %}
                            {% assign img_ration = 1 | divided_by: media.aspect_ratio | times: 100 %}
                            ${this.layout === 'grid' ? `
                            {%- liquid
                                assign check = forloop.index | modulo: 2
                                assign total_after_first = product.media.size | minus: 1
                                assign is_odd_remaining = total_after_first | modulo: 2

                                if forloop.first
                                    assign img_ration = 1 | divided_by: media.aspect_ratio | times: 100
                                elsif forloop.last and is_odd_remaining == 1
                                    assign img_ration = 1 | divided_by: media.aspect_ratio | times: 100
                                else
                                    assign img_ration = 1 | divided_by: media.aspect_ratio | times: 50
                                endif
                            -%}
                            ` : ''}
                            {% assign image = media.preview_image %}
                            {% case media.media_type %}
                                {% when 'image' %}
                                    {%if use_limit and forloop.index > limit_images%}{% break %}{% endif %}
                                    {% assign fetchpriority = 'low'%}
                                    {% assign lazyload = 'lazy'%}
                                    {% if forloop.first %}
                                        {% assign fetchpriority = 'high'%}
                                        {% assign lazyload = 'eager'%}
                                    {% endif %}
                                    <div class="ec_splide__slide ${classNameContainer} ${this.enable_zoom ? ' ecom-image-zoom' :''}" ${this.outerZoom ? 'data-ecom-zoom-layout="outer"' : ''}  data-index="{{forloop.index0}}"  {% if variant_images contains media.src %} data-variant_id="{{ product.images | where: 'src', image.src | map: 'variants' | map: 'id' | join: ',' }}"{% endif %}  style="--img_padding: ${this.heightValue('desktop') ? this.heightValue('desktop') : '{{ img_ration | divided_by:  img_padding }}%'};--img_padding__tablet: ${this.heightValue('tablet') ? this.heightValue('tablet') : '{{ img_ration | divided_by:  img_padding__tablet }}%'};--img_padding__mobile: ${this.heightValue('mobile') ? this.heightValue('mobile') : '{{ img_ration | divided_by:  img_padding__mobile }}%'}" data-half-width="{% assign img_ration_half = 1 | divided_by: image.aspect_ratio | times: 50 %}{{img_ration_half}}" data-full-width="{% assign img_ration_full = 1 | divided_by: media.aspect_ratio | times: 100 %}{{img_ration_full}}">
                                        ${this.data.settings.enable_product_link && !this.enable_zoom && this.data.settings.image_action != 'lightbox' ? `<a href="/products/{{product.handle}}" class="ecom-image-link-product" target="${this.data.settings.open_in_new_window ? '_blank': '_self'}">` : ''}
                                            ${this.enable_zoom ? `<a href="{{ media | image_url: width: 2048}}" class="ecom-img-zoom-a" data-ecom-role="zoom-target">` : ''}
                                                {%- assign img_master = media | image_url: width: 2048 -%}
                                                {{ media | image_url: width: 1946 | image_tag:
                                                    sizes: sizes,
                                                    widths: '246, 493, 600, 713, 823, 990, 1100, 1206, 1346, 1426, 1646, 1946',
                                                    class: 'ecom-image-default'
                                                    ${this.image_action === "lightbox" ? `,ecom-modal-source:img_master , ecom-modal:'image'`: ""}
                                                    ${this.data.settings?.disable_lazyload ? `,loading: 'eager'` : `,loading: lazyload`}
                                                    ,fetchpriority: fetchpriority
                                                    ,alt: media.alt | escape
                                                }}
                                            ${this.enable_zoom ? `</a>` : ''}
                                        ${this.data.settings.enable_product_link && !this.enable_zoom && this.data.settings.image_action != 'lightbox' ? `</a>` : ''}
                                    </div>
                                {% when 'external_video'%}
                                    <div class="${classNameContainer} ecom-product-single__media---external-video ecom-product-single__media--full" data-position="{{media.position}}" style="--img_padding: {{ media_ration | divided_by:  img_padding }}%;--img_padding__tablet: {{ media_ration | divided_by: img_padding__tablet }}%;--img_padding__mobile: {{ media_ration | divided_by: img_padding__mobile }}%;"  ${this.image_action === "lightbox" ? ` ecom-modal='iframe'`: ""}>
                                        {{ media | external_video_tag: image_size:'master' }}
                                    </div>
                                {% when 'video' %}
                                    {% assign videoUrl = '' %}
                                    {% for source in media.sources %}
                                        {% if source.format == "mp4" %}
                                            {% assign videoUrl = source.url %}
                                            {% break %}
                                        {% endif %}
                                    {% endfor %}
                                    <div data-stopdrag="true" class="${classNameContainer} ecom-product-single__media--video ecom-product-single__media--full ecom-swiper-no-swiping" data-position="{{media.position}}" style="--img_padding: ${this.heightValue('desktop') ? this.heightValue('desktop') : '{{ img_ration | divided_by:  img_padding }}%'};--img_padding__tablet: ${this.heightValue('tablet') ? this.heightValue('tablet') : '{{ img_ration | divided_by:  img_padding__tablet }}%'};--img_padding__mobile: ${this.heightValue('mobile') ? this.heightValue('mobile') : '{{ img_ration | divided_by:  img_padding__mobile }}%'}"  ${this.image_action === "lightbox" ? `ecom-modal-source="{{videoUrl}}"  ecom-modal='video'`: ""}>
                                        {{ media | video_tag: image_size:'master', class: 'ecom-media-video', controls: ${this.data.settings?.video_control}, autoplay: ${this.data.settings?.video_auto_play}, muted: ${this.data.settings?.video_mute},loop: ${this.data.settings?.video_loop} }}
                                        ${this.data.settings?.video_auto_play ? ``
                                            : `
                                                <button  class="ecom-product-single__media--play-control" type="button">
                                                    <span class="ecom-product-single__media--play-control-wrapper">
                                                        <span class="visually-hidden">Play video</span>
                                                        ${this.data.settings?.video_icon ? this.data.settings.video_icon.value : ''}
                                                    </span>
                                                </button>
                                            `
                                        }
                                    </div>
                                {% when 'model' %}
                                    <div class="${classNameContainer} ecom-swiper-no-swiping  ecom-product-single__media--model ecom-product-single__media--full" data-stopdrag="true" data-position="{{media.position}}">
                                        <div class="ecom-product-single__media--model-wrapper">
                                            {{ media | model_viewer_tag: image_size:'master', reveal: 'interaction', toggleable: true, data-model-id: media.id }}
                                        </div>
                                    </div>
                                {% else %}
                                    <div data-media-type="{{media.media_type}}" class="${classNameContainer} ecom-swiper-no-swiping ecom-product-single__media--full" data-position="{{media.position}}">
                                        <div class="ecom-product-single__media" style="--img_padding: ${this.heightValue('desktop') ? this.heightValue('desktop') : '{{ img_ration | divided_by:  img_padding }}%'};--img_padding__tablet: ${this.heightValue('tablet') ? this.heightValue('tablet') : '{{ img_ration | divided_by:  img_padding__tablet }}%'};--img_padding__mobile: ${this.heightValue('mobile') ? this.heightValue('mobile') : '{{ img_ration | divided_by:  img_padding__mobile }}%'}">
                                            {{ media | media_tag: image_size:'master', class: 'ecom-product-single__media--item' }}
                                        </div>
                                    </div>
                            {% endcase %}
                        {% endfor %}
                    </div>
                    `,
                    preview: `
                            <div class="ecom-swiper-wrapper ecom-product-single__media-images">
                                <div class="${classNameContainer}">
                                    <img src="https://cdn2.shopify.com/s/files/1/0121/5945/1236/files/backpack.svg?7273" />
                                </div>
                                <div class="${classNameContainer}">
                                    <img loading="lazy" src="https://cdn2.shopify.com/s/files/1/0121/5945/1236/files/shoe.svg?7273" />
                                </div>
                                <div class="${classNameContainer}">
                                    <img loading="lazy" src="https://cdn2.shopify.com/s/files/1/0121/5945/1236/files/shoe.svg?7273" />
                                </div>
                            </div>
                    `
                },
                product_media_thumbs: {
                    code: `
                    {%- if product.media.size > 1 -%}
                    <div class="ec_splide__list ecom-swiper-wrapper{% if product.images.size == 1 %} ecom-product-single__only{% endif %}">
                        {% assign variant_images = product.images | where: 'attached_to_variant?', true | map: 'src' %}
                        {% for media in product.media %}
                            {% if media.media_type == 'image' %}
                                {% assign image = media.preview_image %}
                                {% assign fetchpriority = 'low'%}
                                    {% if forloop.first %}
                                        {% assign fetchpriority = 'high'%}
                                    {% endif %}
                                    <div class="ec_splide__slide ecom-product-single__media--thumbnail ecom-splide-slide"  {% if variant_images contains media.src %} data-variant_id="{{ product.images | where: 'src', image.src | map: 'variants' | map: 'id' | join: ',' }}"{% endif %}>
                                        <img
                                            class="ecom-product-thumbnail"
                                            src="{{ media | image_url: ${this.thumbnail_size.width ? `width: ${this.thumbnail_size.width}` : "width: 300"} ${this.thumbnail_size.height ? `,height: ${this.thumbnail_size.height}` : ""} ${this.thumbnail_crop !== "none" ? `, crop: '${this.thumbnail_crop}'` : ""} }}"
                                            alt="{{ media.alt | escape  }}",
                                            fetchpriority="{{ fetchpriority }}"
                                            style="max-width: 100%; height: auto;"
                                            ${this.data.settings?.disable_lazyload ? '' : `,loading="lazy"`}
                                        />
                                    </div>
                            {% else %}
                                <div class="ec_splide__slide ecom-product-single__media--thumbnail ecom-splide-slide">
                                    <div class="ecom-product-single__media--thumbnail--icon">
                                        {% if media.media_type == 'model' %}
                                            ${this.data.settings?.thumbnail_model_icon ? this.data.settings.thumbnail_model_icon.value: ''}
                                        {% else %}
                                            ${this.data.settings?.thumbnail_video_icon ? this.data.settings.thumbnail_video_icon.value: ''}
                                        {% endif %}
                                    </div>
                                    <img src="{{ media | image_url: ${this.thumbnail_size.width ? `width: ${this.thumbnail_size.width}` : "width: 300"} ${this.thumbnail_size.height ? `,height: ${this.thumbnail_size.height}` : ""} ${this.thumbnail_crop !== "none" ? `, crop: '${this.thumbnail_crop}'` : ""} }}" style="max-width: 100%; height: auto;"  alt="{{ media.alt | escape }}" ${this.data.settings?.disable_lazyload ? '' : `loading="lazy"`}/>
                                </div>
                            {% endif %}
                        {% endfor %}
                    </div>
                    {%- endif -%}
                    `,
                    preview: `
                        <div class="ecom-swiper-wrapper">
                        <div class="ecom-product-single__media--thumbnail ecom-splide-slide">
                            <img class="ecom-product-thumbnail" width="100"  src="https://cdn2.shopify.com/s/files/1/0121/5945/1236/files/backpack.svg?7273" />
                        </div>
                        <div class="ecom-product-single__media--thumbnail ecom-splide-slide">
                            <img class="ecom-product-thumbnail"  width="100" src="https://cdn2.shopify.com/s/files/1/0121/5945/1236/files/shoe.svg?7273" />
                        </div>
                        <div class="ecom-product-single__media--thumbnail ecom-splide-slide">
                            <img class="ecom-product-thumbnail" width="100"  src="https://cdn2.shopify.com/s/files/1/0121/5945/1236/files/shoe.svg?7273" />
                        </div>
                    </div>
                    `
                },
                thumb_count_class: {
                    code: `
                        {% if product.media.size == 1 %}
                            ecom-dont-has-many-images
                         {% endif %}
                    `,
                    preview: ""
                },
                product_model: {
                    code: `
                        <${tagName} type="application/json" id="Product-model-{{ product.id }}">
                            {{ product.media | where: 'media_type', 'model' | json }}
                        </${tagName}>
                    `,
                    preview: ""
                },
                featured_image: {
                    code: `
                            ${label}
                            <div class="${classNameContainer} ${this.enable_zoom ? ' ecom-image-zoom' :''}" ${this.outerZoom ? 'data-ecom-zoom-layout="outer"' : ''}" style="--img_padding: ${this.heightValue('desktop') ? this.heightValue('desktop') : '{{ 1 | divided_by: product.featured_image.aspect_ratio | times: 100 }}%'};--img_padding__tablet: ${this.heightValue('tablet') ? this.heightValue('tablet') : '{{ 1 | divided_by: product.featured_image.aspect_ratio | times: 100 }}%'};--img_padding__mobile: ${this.heightValue('mobile') ? this.heightValue('mobile') : '{{ 1 | divided_by: product.featured_image.aspect_ratio | times: 100 }}%'}" data-variant_id="{{ product.featured_image.variants | map:'id' | join: ','  }}">
                                ${this.data.settings.enable_product_link && !this.enable_zoom && this.data.settings.image_action != 'lightbox' ? `<a href="/products/{{product.handle}}" class="ecom-image-link-product" target="${this.data.settings.open_in_new_window ? '_blank': '_self'}">` : ''}
                                ${this.enable_zoom ? `<a href="{{ product.featured_image | image_url: width: 2048 }}" class="ecom-img-zoom-a" data-ecom-role="zoom-target">` : ''}
                                    {% if product.featured_image %}
                                        {%- assign img_master = product.featured_image | image_url: width: 2048 -%}
                                        {{ product.featured_image | image_url: width: 1946 | image_tag:
                                            loading: eager,
                                            fetchpriority: 'high',
                                            sizes: sizes,
                                            widths: '246, 493, 600, 713, 823, 990, 1100, 1206, 1346, 1426, 1646, 1946',
                                            class: 'ecom-image-default'
                                            ${this.image_action === "lightbox" ? `,ecom-modal-source:img_master , ecom-modal:'image'`: ""}
                                            ,alt: product.featured_image.alt | escape
                                        }}
                                    {% else %}
                                        <img src="https://cdn2.shopify.com/s/files/1/0121/5945/1236/files/backpack.svg?7273" />
                                    {% endif %}
                                ${this.enable_zoom ? `</a>` : ''}
                                ${this.data.settings.enable_product_link && !this.enable_zoom && this.data.settings.image_action != 'lightbox' ? `</a>` : ''}
                            </div>
                        `,
                    preview: `
                        <div class="${classNameContainer}">
                                <img src="https://cdn2.shopify.com/s/files/1/0121/5945/1236/files/backpack.svg?7273" />
                        </div>
                        `
                }
            };
            if (this.layout === "slider" && this.show_thumbnails) {
                return {
                    product_media: liquids.product_media,
                    product_media_thumbs: liquids.product_media_thumbs,
                    product_model: liquids.product_model,
                    thumb_count_class : liquids.thumb_count_class,
                    checkProduct: liquids.checkProduct
                };
            }
            if (this.layout === "single") {
                return {
                    featured_image: liquids.featured_image,
                    checkProduct: liquids.checkProduct
                };
            }
            return {
                product_media: liquids.product_media,
                product_model: liquids.product_model,
                product_grid: liquids.product_grid,
                checkProduct: liquids.checkProduct
            };
        },

        css() {
            return `
                .ecom-product-single__media-container .ecom-swiper-container.ecom-product-single__media--featured {
                    overflow-y: unset !important;
