        "data.settings.thumbnail_position__mobile": {
            immediate: true,
            handler() {
                this.$helpers.dispatchResize();
            }
        },
        "data.settings.slidesPerView": function () {
            this.$helpers.dispatchResize();
        },
        watcherSliderPagination: {
            immediate: true,
            handler() {
                this.debounce(() => {
                    if(this.$el) {
                        const $sliderElement = this.$el.querySelector(
                            ".ecom-product-single__media--featured"
                        );
                        let slider = $sliderElement.ec_splide;
                        if(slider) {
                            slider.Components?.Pagination?.resetPagination();
                        }
                    }
                }, 500);
            },
            deep: true
        },
        screen(newVal, oldVal) {
            const $el = this.$el;

            if (!$el || !($el instanceof HTMLElement)) return;

            if ( this.data?.settings?.position_sticky ) {

                if ($el.parentElement) {
                    const targetEl = $el.parentElement;

                    const checkEl = $el.parentElement.parentElement;
                    if (!checkEl) return;
                    const isNewStruct = checkEl.classList.contains('ecom-inner') || checkEl.classList.contains('ec-flex-wp');

                    if (newVal === 'desktop') {
                        targetEl.style.height = isNewStruct ? 'auto' : '100%';
                    } else {
                        targetEl.style.height =  'auto';
                    }
                }
            }
        },
        'data.settings.metafield_label': {
            handler(newVal) {
                if (this._debouncedMetafieldCodeTimer) {
                    clearTimeout(this._debouncedMetafieldCodeTimer);
                }
                this._debouncedMetafieldCodeTimer = setTimeout(() => {
                    this.validMetafieldCode = safeMetafieldCode(newVal);
                }, 500);
            },
        },
    },
    methods: {
         heightValue(screen) {
            switch(screen) {
                case 'desktop':
                    return this.data.style?.product_image?.imageHeight && this.data.style?.product_image?.imageHeight != 'none'
                        ? this.data.style.product_image.imageHeight
                        : false;
                case 'tablet':
                    return this.data.style?.product_image?.imageHeight__tablet && this.data.style?.product_image?.imageHeight__tablet != 'none'
                        ? this.data.style.product_image.imageHeight__tablet
                        : false;
                case 'mobile':
                    return this.data.style?.product_image?.imageHeight__mobile && this.data.style?.product_image?.imageHeight__mobile != 'none'
                        ? this.data.style.product_image.imageHeight__mobile
                        : false;
            }
        },
        get_row_items(qty) {
            switch (parseInt(qty)) {
                case 12:
                    return 1;
                case 6:
                    return 2;
                case 4:
                    return 3;
                case 3:
                    return 4;
                case 15:
                    return 5;
                case 2:
                    return 6;
                default:
                    return 1;
            }
        },
        debounce(fn, wait) {
            clearTimeout(this.debouncedResetPagination);
            this.debouncedResetPagination = setTimeout(fn, wait);
        }
    }
};
